package main

import "fmt"

func worker(ch chan<- string) {
	// some work...
	result := "done"
	ch <- result // blocks until main is ready to receive (rendezvous)
}

func main() {
	ch := make(chan string) // unbuffered: capacity 0

	go worker(ch) // launch the producer

	msg := <-ch // blocks until worker sends; pairs the two goroutines
	fmt.Println("received:", msg)

	// Because the send happens-before this receive completed,
	// everything worker did before `ch <- result` is visible here.
}

package main

import "fmt"

func produce(out chan<- int) {
	for i := 1; i <= 3; i++ {
		out <- i // each send rendezvous with the range receive
	}
	close(out) // SENDER closes: signals 'no more values'
}

func main() {
	ch := make(chan int)
	go produce(ch)

	// range receives until the channel is closed AND drained,
	// then the loop ends automatically.
	for v := range ch {
		fmt.Println("got", v)
	}

	// After close+drain, a receive returns the zero value with ok=false.
	v, ok := <-ch
	fmt.Printf("after close: v=%d ok=%t\n", v, ok)
}

package main

import (
	"fmt"
	"time"
)

func main() {
	a := make(chan string)
	b := make(chan string)

	go func() { time.Sleep(50 * time.Millisecond); a <- "from a" }()
	go func() { time.Sleep(150 * time.Millisecond); b <- "from b" }()

	// Non-blocking poll: nothing is ready yet, so default runs.
	select {
	case v := <-a:
		fmt.Println(v)
	default:
		fmt.Println("nothing ready yet")
	}

	// Wait for whichever of a, b is ready first, but give up after 100ms.
	for i := 0; i < 2; i++ {
		select {
		case v := <-a:
			fmt.Println("received", v)
		case v := <-b:
			fmt.Println("received", v)
		case <-time.After(100 * time.Millisecond):
			fmt.Println("timeout waiting for a value")
		}
	}
}
